$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$python = Join-Path $root ".venv\Scripts\python.exe"
$businessUnitsPath = Join-Path $pkg "ahos\business_units.py"
$studioPath = Join-Path $pkg "ahos\animation_studio.py"
$testPath = Join-Path $pkg "tests\test_animation_studio.py"
$studioBacklogPath = Join-Path $pkg "STUDIO_BACKLOG.json"
$reportDir = Join-Path $pkg "reports"
$reportPath = Join-Path $reportDir "STUDIO-001-animation-studio-blueprint.json"

Write-Host "=== STUDIO-001 ANIMATION STUDIO BUSINESS UNIT ==="
Write-Host "AHOS core is already COMPLETE."
Write-Host "This begins the Animation Studio phase."
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""

if (-not (Test-Path $python)) { throw "Python venv not found." }
if (-not (Test-Path $pkg)) { throw "AHOS package not found." }

New-Item -ItemType Directory -Force -Path $reportDir | Out-Null

[IO.File]::WriteAllBytes(
    $businessUnitsPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $studioPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $testPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $studioBacklogPath,
    [Convert]::FromBase64String("")
)

$old = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg

    Write-Host "Running Animation Studio tests..."
    & $python -m pytest tests\test_animation_studio.py -q
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-001 focused tests failed."
    }

    Write-Host "Running full AHOS regression suite..."
    & $python -m pytest -q
    if ($LASTEXITCODE -ne 0) {
        throw "Full AHOS regression suite failed."
    }

    Write-Host "Writing studio blueprint..."
    & $python -c "from ahos.animation_studio import animation_studio_blueprint, write_animation_studio_blueprint; s=animation_studio_blueprint(); write_animation_studio_blueprint(r'$reportPath'); print('BUSINESS UNIT:',s.name); print('TEAMS:',len(s.teams)); print('STUDIO WORKERS:',len(s.workers)); print('DIRECTOR:',s.director_worker_id); [print(t.team_id,'->',t.lead_worker_id) for t in s.teams]"
    if ($LASTEXITCODE -ne 0) {
        throw "Studio blueprint generation failed."
    }
}
finally {
    Pop-Location
    $env:PYTHONPATH = $old
}

git -C $ws add `
    ahos_core/ahos/business_units.py `
    ahos_core/ahos/animation_studio.py `
    ahos_core/tests/test_animation_studio.py `
    ahos_core/STUDIO_BACKLOG.json `
    ahos_core/reports/STUDIO-001-animation-studio-blueprint.json

$staged = git -C $ws diff --cached --name-only
if ($staged) {
    git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" `
        commit -m "feat(studio): create animation studio business unit"
    if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

    git -C $ws push origin HEAD
    if ($LASTEXITCODE -ne 0) { throw "git push failed." }
} else {
    Write-Host "Git: no staged changes; STUDIO-001 already present."
}

Write-Host ""
Write-Host "=== STUDIO-001 COMPLETE ==="
Write-Host "Generic holding business-unit model: PASS"
Write-Host "Animation Studio business unit: PASS"
Write-Host "Studio teams: 8"
Write-Host "Studio virtual workers: 20"
Write-Host "Reporting hierarchy / cycle validation: PASS"
Write-Host "Owner reserved decisions: PASS"
Write-Host "Paid AI default: OFF"
Write-Host "External actions default: OFF"
Write-Host "Full AHOS regression suite: PASS"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""
Write-Host "STUDIO ROADMAP: STUDIO-001 through STUDIO-008."
Write-Host "NEXT: STUDIO-002 persistent Character Bible and continuity memory."
